            if (x === null || x === "" || x === undefined) return 1; if (y === null || y === "" || y === undefined) return -1;
            const cmp = typeof x === "number" && typeof y === "number" ? x - y : String(x).localeCompare(String(y), undefined, { sensitivity: "base" });
            if (cmp) return d === "asc" ? cmp : -cmp;
