        const rs = D.runners.filter(r => r.seasons.includes(s)), rm = rs.filter(r => r.results.some(x => x.m.season === s && !isHS(x.m))).length, rh = rs.filter(r => r.results.some(x => x.m.season === s && isHS(x.m))).length;
